Next best step: make the terminal version robust before adding more effects.

1. Use a terminal that supports ANSI colors.
2. Keep `WIDTH` slightly smaller than your terminal width to avoid wrapping.
3. Add cleanup so the cursor is restored on exit.
4. Use a single `sleep_ms()` helper for portability.

Minimal safe structure:

```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#ifdef _WIN32
#include <windows.h>
#define sleep_ms(ms) Sleep(ms)
#else
#include <unistd.h>
#define sleep_ms(ms) usleep((ms) * 1000)
#endif

volatile sig_atomic_t running = 1;

void stop_program(int signal) {
    (void)signal;
    running = 0;
}

void cleanup(void) {
    printf("\033[0m\033[?25h\n"); // Reset color and show cursor
    fflush(stdout);
}

int main(void) {
    signal(SIGINT, stop_program);
    atexit(cleanup);

    printf("\033[2J\033[H\033[?25l"); // Clear and hide cursor

    int frame = 0;

    while (running) {
        printf("\033[H");

        for (int y = 0; y < 20; y++) {
            for (int x = 0; x < 70; x++) {
                int bit = ((x + y + frame) % 9 == 0) ? 1 : 0;
                printf("%d", bit);
            }
            printf("\n");
        }

        fflush(stdout);
        frame++;
        sleep_ms(70);
    }

    return 0;
}
```

